(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.33)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const w2x = Math.sin(x*0.025-t*0.4)*10 + Math.cos(y*0.02+t*0.35)*7;
  const w2y = Math.cos(y*0.022+t*0.38)*10 + Math.sin(x*0.019-t*0.42)*7;
  const sx = x+w1x, sy = y+w1y;
  const sx2 = x+w2x, sy2 = y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.085, 1.8, 1.05],
    [200+Math.sin(t*0.7)*90, 220+Math.cos(t*0.3)*70, 0.075, 2.4, 0.9],
    [300+Math.cos(t*0.42+1)*110, 30+Math.sin(t*0.58+2)*55, 0.095, 2.0, 1.15]
  ];
  let aS=0, iS=0, cross=0;
  for(const [sX,sY,f,sp,w] of src){
    const d1=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2=Math.sqrt((sx2-sX)**2+(sy2-sY)**2);
    aS+=Math.sin(d1*f-t*sp)*w;
    iS+=Math.sin(d1*f*0.7+t*sp*0.6+1.5)*w;
    cross+=Math.sin((d1+d2)*f*0.5-t*sp*0.8)*w*0.6;
  }
  const aSn=aS/8.45, iSn=iS/8.45, crossN=cross/5.07;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07*Math.cos(t*0.2)+sy*0.05*Math.sin(t*0.3)+t*1.8)*0.15;
