  const moire=Math.sin(sx*0.22)*Math.sin(sy*0.22)+Math.sin((sx-sy)*0.16+t)*Math.sin((sx+sy)*0.16-t*0.7);
  const laplacian=(Math.sin(sx*0.15+0.01)+Math.sin(sx*0.15-0.01)+Math.sin(sy*0.15+0.01)+Math.sin(sy*0.15-0.01)-4*Math.sin(sx*0.15)*Math.sin(sy*0.15))*0.5;
  const react=Math.tanh((aSn-iSn*0.7+bg*0.3+spiral+crossN*0.4+moire*0.15+laplacian*0.3)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin((sx-sy*0.7)*0.12-t*0.8)*0.3)*1.5)*0.3;
  const glow=Math.exp(-Math.abs(react)*3)*0.15;
  const blend=react*0.65+cell*0.2+glow*0.15, v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[12,45,95],[18,85,130],[25,135,145],[45,170,155],
    [140,195,120],[210,195,75],[225,155,60],[200,95,70],[160,50,75],
    [100,25,65],[45,15,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const edge=Math.abs(react)>0.65?1.2:1.0;
  const shimmer=1.0+Math.sin(react*Math.PI*2)*0.06+Math.sin(crossN*Math.PI)*0.04;
  const lum=edge*shimmer;
